/* 水果素材：为水果词条补充插画路径（渲染层缺图时仍回退 emoji） */
const FRUIT_IMAGES = {
  apple: "apple", banana: "banana", grape: "grape", orange: "orange", strawberry: "strawberry",
  pineapple: "pineapple", watermelon: "watermelon", lemon: "lemon", blueberry: "blueberry",
  cherry: "cherry", peach: "peach", pear: "pear", kiwi: "kiwi", mango: "mango",
  melon: "melon", cupcake: "cupcake", donut: "donut", bread: "bread",
};
Object.keys(FRUIT_IMAGES).forEach((key) => {
  const w = window.DINO_WORD_LIBRARY[key];
  if (w) w.img = `images/words/food/${FRUIT_IMAGES[key]}.webp`;
});
/* 把主题里的引用数组解析成完整词条；库里缺失时保留原引用并告警 */
window.resolveWordRefs = function (refs) {
  return (refs || []).map((ref) => {
    const id = typeof ref === "string" ? ref : ref && ref.word;
    const base = window.DINO_WORD_LIBRARY[id];
    if (!base) { console.warn("[word-library] 词条缺失:", id); return typeof ref === "string" ? { word: ref } : { ...ref }; }
    return typeof ref === "string" ? { ...base } : { ...base, ...ref };
  });
};
/* 词性池：单次遍历总库按 category 分桶重建（避免 5 轮全库重复扫描） */
window.DINO_WORD_SETS = window.DINO_WORD_SETS || [];
(function () {
  const buckets = { noun: [], verb: [], adj: [], adv: [], num: [] };
  const lib = window.DINO_WORD_LIBRARY;
  for (const key in lib) {
    const w = lib[key];
    const list = w && buckets[w.category];
    if (list) list.push(Object.assign({}, w, { key }));
  }
  ["noun", "verb", "adj", "adv", "num"].forEach((pos) => {
    if (buckets[pos].length) window.DINO_WORD_SETS.push({ id: pos, isPool: true, words: buckets[pos] });
  });
})();
